/**
 * Web Tests Aggregator Service
 *
 * Aggregates test status from multiple Allure projects for the Web (doc2app) service.
 * Queries environment-specific projects and returns simple pass/fail status.
 *
 * Used by /tests page to display current test status for the Web service.
 *
 * Test categories (ordered from unit to E2E):
 * - Unit Tests (Vitest)
 * - Component Tests (Vitest)
 * - Integration Tests (Vitest)
 * - API Integration Tests (Vitest)
 * - E2E Tests (Playwright)
 */

import { allureApiService } from '../allure';
import { logger } from 'src/utils/logger';

/**
 * Test category status
 */
export interface TestCategoryStatus {
  name: string;
  displayName: string;
  allPassing: boolean;
  totalTests: number;
  failedTests: number;
  lastRunAt: Date | null;
  projectId: string; // Allure project ID for direct linking
  hasData?: boolean; // false when report unavailable or totalTests === 0
}

/**
 * Overall Web service test status
 */
export interface WebTestsStatus {
  service: 'web';
  displayName: string;
  environment: string; // 'dev', 'stage', 'prod', etc.
  allPassing: boolean;
  categories: TestCategoryStatus[];
  totalTests: number;
  totalFailed: number;
  lastUpdated: Date;
}

/**
 * Service that aggregates test results from all Web test categories
 */
export class WebTestsAggregatorService {
  /**
   * Get test status for Web service in current environment
   *
   * Queries all environment-specific Allure projects and returns
   * aggregated pass/fail status for display on /tests page.
   *
   * @param environment - Current environment (dev, stage, prod, etc.)
   * @returns WebTestsStatus object with all test category statuses
   *
   * @example
   * const status = await webTestsAggregatorService.getWebTestsStatus('dev');
   * console.log(`All passing: ${status.allPassing}`);
   * console.log(`Total failed: ${status.totalFailed} of ${status.totalTests}`);
   */
  async getWebTestsStatus(environment: string): Promise<WebTestsStatus> {
    logger.info(`[WebTestsAggregator] Fetching test status for environment: ${environment}`);

    const categories: TestCategoryStatus[] = [];

    // Use environment-specific Allure projects for each test category
    // Projects created by deployment.yaml with force_project_creation=true
    // Ordered from unit level up to E2E (most fundamental → most comprehensive)
    const testCategories = [
      {
        name: 'unit',
        displayName: 'Unit Tests',
        projectId: `web-unit-tests-${environment}`,
      },
      {
        name: 'component',
        displayName: 'Component Tests',
        projectId: `web-component-tests-${environment}`,
      },
      {
        name: 'integration',
        displayName: 'Integration Tests',
        projectId: `web-integration-tests-${environment}`,
      },
      {
        name: 'api-integration',
        displayName: 'API Integration Tests',
        projectId: `web-api-integration-tests-${environment}`,
      },
      {
        name: 'e2e',
        displayName: 'E2E Tests',
        projectId: `web-e2e-tests-${environment}`,
      },
    ];

    // Check status for each category in parallel for better performance
    const categoryPromises = testCategories.map(async (category) => {
      try {
        const report = await allureApiService.getLatestReport(category.projectId);

        const status: TestCategoryStatus = {
          name: category.name,
          displayName: category.displayName,
          projectId: category.projectId,
          allPassing: report
            ? report.statistic.failed + report.statistic.broken === 0
            : false,
          totalTests: report?.statistic.total || 0,
          failedTests: report ? report.statistic.failed + report.statistic.broken : 0,
          lastRunAt: report ? new Date(report.time.stop) : null,
        };

        logger.debug(`[WebTestsAggregator] ${category.displayName}:`, {
          allPassing: status.allPassing,
          totalTests: status.totalTests,
          failedTests: status.failedTests,
        });

        return status;
      } catch (error) {
        logger.error(`[WebTestsAggregator] Error fetching ${category.displayName}:`, error);

        // Return failed status on error
        return {
          name: category.name,
          displayName: category.displayName,
          projectId: category.projectId,
          allPassing: false,
          totalTests: 0,
          failedTests: 0,
          lastRunAt: null,
        };
      }
    });

    // Wait for all category statuses
    const resolvedCategories = await Promise.all(categoryPromises);
    categories.push(...resolvedCategories);

    // Calculate overall status
    const allPassing = categories.every((cat) => cat.allPassing);
    const totalTests = categories.reduce((sum, cat) => sum + cat.totalTests, 0);
    const totalFailed = categories.reduce((sum, cat) => sum + cat.failedTests, 0);

    logger.info(`[WebTestsAggregator] Aggregated status for ${environment}:`, {
      allPassing,
      totalTests,
      totalFailed,
      categoriesChecked: categories.length,
    });

    return {
      service: 'web',
      displayName: 'Web Application',
      environment,
      allPassing,
      categories,
      totalTests,
      totalFailed,
      lastUpdated: new Date(),
    };
  }

  /**
   * Get status for a specific test category
   *
   * @param environment - Current environment
   * @param categoryName - Category name (e.g., 'unit', 'component')
   * @returns TestCategoryStatus or null if not found
   */
  async getCategoryStatus(
    environment: string,
    categoryName: string
  ): Promise<TestCategoryStatus | null> {
    const fullStatus = await this.getWebTestsStatus(environment);
    return fullStatus.categories.find((cat) => cat.name === categoryName) || null;
  }
}

// Export singleton instance
export const webTestsAggregatorService = new WebTestsAggregatorService();
